-- ============================================================
-- Thick Hide: wiring
-- ============================================================
--
-- TODO.md: "Thick Hide (2, 1): Increases the armor rating of your pets by 20%,
-- and their chance to dodge is increased by your agility. (3 ranks) (Similar to
-- demo lock talent)"
--
-- The armor half was already +7/13/20% (Effect1, ADD_FLAT_MODIFIER, MiscValue 8,
-- class mask 0x4000000 = the pet scaling chain) and is NOT touched.
--
-- The replaced half is Effect2, which in retail was MOD_BASE_RESISTANCE_PCT
-- (MiscValue 1) giving the HUNTER +4/7/10% armor from items -- a hunter bonus on
-- a pet talent.  It becomes the spell_pet_auras carrier at effectId 1.
--
-- The "demo lock talent" the TODO points at is Demonic Embrace
-- (spell_warl_demon_dodge, WarlockDemonPets.cpp:161), and the hunter version is
-- the same script with three substitutions: STAT_AGILITY rather than
-- STAT_INTELLECT, and the hunter's own crit-to-dodge coefficient and class row
-- in gtChanceToMeleeCrit.  Amount 0 in the DBC because C++ writes it.
DELETE FROM `spell_pet_auras` WHERE `spell` IN (19609, 19610, 19612);
INSERT INTO `spell_pet_auras` (`spell`, `effectId`, `pet`, `aura`) VALUES
(19609, 1, 0, 200747),
(19610, 1, 0, 200747),
(19612, 1, 0, 200747);

